export default JSON.parse("{\"workId\":\"han-fei-zi\",\"chapter\":{\"id\":\"han-fei-zi_ch-19\",\"workId\":\"han-fei-zi\",\"order\":19,\"title\":\"難二\",\"difficulty\":4,\"estimatedMinutes\":11,\"passageIds\":[\"han-fei-zi_ch-19_p-1\",\"han-fei-zi_ch-19_p-2\",\"han-fei-zi_ch-19_p-3\",\"han-fei-zi_ch-19_p-4\",\"han-fei-zi_ch-19_p-5\",\"han-fei-zi_ch-19_p-6\",\"han-fei-zi_ch-19_p-7\",\"han-fei-zi_ch-19_p-8\",\"han-fei-zi_ch-19_p-9\",\"han-fei-zi_ch-19_p-10\",\"han-fei-zi_ch-19_p-11\",\"han-fei-zi_ch-19_p-12\",\"han-fei-zi_ch-19_p-13\",\"han-fei-zi_ch-19_p-14\"],\"tags\":[\"法家\",\"帝王術\",\"法術勢\"]},\"passages\":[{\"id\":\"han-fei-zi_ch-19_p-1\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":1,\"canonicalText\":\"景公過晏子曰：「子宮小，近市，請徙子家豫章之圃。」晏子再拜而辭曰：「且嬰家貧，待市食，而朝暮趨之，不可以遠。」景公笑曰：「子家習市，識貴賤乎？」是時景公繁於刑，晏子對曰：「踴貴而屨賤。」景公曰：「何故？」對曰：「刑多也。」景公造然變色曰：「寡人其暴乎！」於是損刑五。\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-1_s-1\",\"han-fei-zi_ch-19_p-1_s-2\",\"han-fei-zi_ch-19_p-1_s-3\",\"han-fei-zi_ch-19_p-1_s-4\",\"han-fei-zi_ch-19_p-1_s-5\",\"han-fei-zi_ch-19_p-1_s-6\",\"han-fei-zi_ch-19_p-1_s-7\",\"han-fei-zi_ch-19_p-1_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 1 節）中闡述道：景公過晏子說道：：子宮小，近市，請徙子家豫章的圃。晏子再拜而且辭說道：：且嬰家貧，待市食，而且朝暮趨的，不可以遠。景公笑說道：：子家習市，識貴賤乎？是時景公繁於刑，晏子對說道：：踴貴而且屨賤。景公說道：：何所以？對說道：：刑多啊。景公造然變色說道：：寡人他的暴乎！於是損刑五。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 1 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「景公過晏子曰：「子宮小，近市，請徙子家豫章之圃」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「景公過晏子曰：「子宮小，近市，請徙子家豫章之圃。」晏……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-2\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":2,\"canonicalText\":\"或曰：晏子之貴踴，非其誠也，欲便辭以止多刑也，此不察治之患也。夫刑當無多，不當無少，無以不當聞，而以太多說，無術之患也。敗軍之誅以千百數，猶北不止。即治亂之刑如恐不勝，而姦尚不盡。今晏子不察其當否，而以太多為說，不亦妄乎！夫惜草茅者耗禾穗，惠盜賊者傷良民。今緩刑罰，行寬惠，是利姦邪而害善人也，此非所以為治也。\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-2_s-1\",\"han-fei-zi_ch-19_p-2_s-2\",\"han-fei-zi_ch-19_p-2_s-3\",\"han-fei-zi_ch-19_p-2_s-4\",\"han-fei-zi_ch-19_p-2_s-5\",\"han-fei-zi_ch-19_p-2_s-6\",\"han-fei-zi_ch-19_p-2_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 2 節）中闡述道：或說道：：晏子的貴踴，絕不是他的誠啊，欲便辭以止多刑啊，此不察治的患啊。夫刑當無多，不當無少，無以不當聞，而且以太多說，無御臣心術權謀的患啊。敗軍的誅以千百數，猶北不止。即治亂的刑如恐不勝，而且姦尚不盡。今晏子不察他的當否，而且以太多為說，不亦妄乎！夫惜草茅的人或事物耗禾穗，惠盜賊的人或事物傷良民。今緩刑刑罰制裁，行寬惠，是利姦邪而且害善人啊，此絕不是所以為治啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 2 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「或曰：晏子之貴踴，非其誠也，欲便辭以止多刑也，此不察治之患也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「或曰：晏子之貴踴，非其誠也，欲便辭以止多刑也，此不察……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-3\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":3,\"canonicalText\":\"齊桓公飲酒醉，遺其冠，恥之，三日不朝。管仲曰：「此非有國之恥也，公胡其不雪之以政？」公曰：「胡其善。」因發倉囷，賜貧窮；論囹圄，出薄惱。處三日而民歌之曰：「公胡不復遺冠乎！」\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-3_s-1\",\"han-fei-zi_ch-19_p-3_s-2\",\"han-fei-zi_ch-19_p-3_s-3\",\"han-fei-zi_ch-19_p-3_s-4\",\"han-fei-zi_ch-19_p-3_s-5\",\"han-fei-zi_ch-19_p-3_s-6\",\"han-fei-zi_ch-19_p-3_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 3 節）中闡述道：齊桓公飲酒醉，遺他的冠，恥的，三日不朝。管仲說道：：此絕不是有國的恥啊，公胡他的不雪的以政？公說道：：胡他的善。因發倉囷，賜貧窮；論囹圄，出薄惱。處三日而且民歌的說道：：公胡不復遺冠乎！這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 3 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊桓公飲酒醉，遺其冠，恥之，三日不朝」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊桓公飲酒醉，遺其冠，恥之，三日不朝。管仲曰：「此非……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-4\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":4,\"canonicalText\":\"或曰：管仲雪桓公之恥於小人，而生桓公之恥於君子矣。使桓公發倉囷而賜貧窮，論囹圄而出薄惱，非義也，不可以雪恥使之而義也。桓公宿義，須遺冠而後行之，則是桓公行義，非為遺冠也。是雖雪遺冠之恥於小人，而亦遺義之恥於君子矣。且夫發囷倉而賜貧窮者，是賞無功也；論囹圄而出薄惱者，是不誅過也。夫賞無功則民偷幸而望於上，不誅過則民不懲而易為非，此亂之本也，安可以雪恥哉？\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-4_s-1\",\"han-fei-zi_ch-19_p-4_s-2\",\"han-fei-zi_ch-19_p-4_s-3\",\"han-fei-zi_ch-19_p-4_s-4\",\"han-fei-zi_ch-19_p-4_s-5\",\"han-fei-zi_ch-19_p-4_s-6\",\"han-fei-zi_ch-19_p-4_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 4 節）中闡述道：或說道：：管仲雪桓公的恥於小人，而且生桓公的恥於君主統治者子矣。使桓公發倉囷而且賜貧窮，論囹圄而且出薄惱，絕不是義啊，不可以雪恥使的而且義啊。桓公宿義，須遺冠而且後行的，則是桓公行義，絕不是為遺冠啊。是雖雪遺冠的恥於小人，而且亦遺義的恥於君主統治者子矣。再的人或事物況且發囷倉而且賜貧窮的人或事物，是賞賜恩惠無功啊；論囹圄而且出薄惱的人或事物，是不誅過啊。夫賞賜恩惠無功則民偷幸而且望於上，不誅過則民不懲而且易為絕不是，此亂的本啊，安可以雪恥哉？這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 4 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「或曰：管仲雪桓公之恥於小人，而生桓公之恥於君子矣」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「或曰：管仲雪桓公之恥於小人，而生桓公之恥於君子矣。使……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-5\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":5,\"canonicalText\":\"昔者文王侵孟、克莒、舉酆，三舉事而紂惡之，文王乃懼，請入洛西之地、赤壤之國、方千里以請解炮烙之刑，天下皆說。仲尼聞之曰：「仁哉文王！輕千里之國而請解炮烙之刑。智哉文王！出千里之地而得天下之心。」\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-5_s-1\",\"han-fei-zi_ch-19_p-5_s-2\",\"han-fei-zi_ch-19_p-5_s-3\",\"han-fei-zi_ch-19_p-5_s-4\",\"han-fei-zi_ch-19_p-5_s-5\",\"han-fei-zi_ch-19_p-5_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 5 節）中闡述道：昔的人或事物文王侵孟、克莒、舉酆，三舉事而且紂惡的，文王乃懼，請入洛西的地、赤壤的國、方千里以請解炮烙的刑，天下皆說。仲尼聞的說道：：仁哉文王！輕千里的國而且請解炮烙的刑。智哉文王！出千里的地而且得天下的心。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 5 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「昔者文王侵孟、克莒、舉酆，三舉事而紂惡之，文王乃懼，請入洛西之地、赤壤之國、方千里以請解炮烙之刑，天下皆說」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「昔者文王侵孟、克莒、舉酆，三舉事而紂惡之，文王乃懼，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-6\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":6,\"canonicalText\":\"或曰：仲尼以文王為智也，不亦過乎！夫智者知禍難之地而闢之者也，是以身不及於患也。使文王所以見惡於紂者，以其不得人心耶？則雖索人心以解惡可也。紂以其大得人心而惡之，己又輕地以收人心，是重見疑也。固其所以桎梏囚於羑里也。鄭長者有言：「體道，無為、無見也。」此最宜於文王矣，不使人疑之也。仲尼以文王為智，未及此論也。\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-6_s-1\",\"han-fei-zi_ch-19_p-6_s-2\",\"han-fei-zi_ch-19_p-6_s-3\",\"han-fei-zi_ch-19_p-6_s-4\",\"han-fei-zi_ch-19_p-6_s-5\",\"han-fei-zi_ch-19_p-6_s-6\",\"han-fei-zi_ch-19_p-6_s-7\",\"han-fei-zi_ch-19_p-6_s-8\",\"han-fei-zi_ch-19_p-6_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 6 節）中闡述道：或說道：：仲尼以文王為智啊，不亦過乎！夫智的人或事物知禍難的地而且闢的的人或事物啊，是以身不及於患啊。使文王所以見惡於紂的人或事物，以他的不得人心耶？則雖索人心以解惡可啊。紂以他的大得人心而且惡的，己又輕地以收人心，是重見疑啊。固他的所以桎梏囚於羑里啊。鄭長的人或事物有言：體道，無為、無見啊。此最宜於文王矣，不使人疑的啊。仲尼以文王為智，未及此論啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 6 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「或曰：仲尼以文王為智也，不亦過乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「或曰：仲尼以文王為智也，不亦過乎！夫智者知禍難之地而……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-7\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":7,\"canonicalText\":\"晉平公問叔向曰：「昔者齊桓公九合諸侯，一匡天下，不識臣之力也？君之力也？」叔向對曰：「管仲善制割，賓胥無善削縫，隰朋善純緣，衣成，君舉而服之，亦臣之力也，君何力之有？」師曠伏琴而笑之。公曰：「太師奚笑也？」師曠對曰：「臣笑叔向之對君也。凡為人臣者，猶炮宰和五味而進之君，君弗食，孰敢強之也。臣請譬之：君者、壤地也，臣者、草木也，必壤地美然後草木碩大，亦君之力也，臣何力之有？」\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-7_s-1\",\"han-fei-zi_ch-19_p-7_s-2\",\"han-fei-zi_ch-19_p-7_s-3\",\"han-fei-zi_ch-19_p-7_s-4\",\"han-fei-zi_ch-19_p-7_s-5\",\"han-fei-zi_ch-19_p-7_s-6\",\"han-fei-zi_ch-19_p-7_s-7\",\"han-fei-zi_ch-19_p-7_s-8\",\"han-fei-zi_ch-19_p-7_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 7 節）中闡述道：晉平公問叔向說道：：昔的人或事物齊桓公九合諸侯，一匡天下，不識臣下僚屬的力啊？君主統治者的力啊？叔向對說道：：管仲善制割，賓胥無善削縫，隰朋善純緣，衣成，君主統治者舉而且服的，亦臣下僚屬的力啊，君主統治者何力的有？師曠伏琴而且笑的。公說道：：太師奚笑啊？師曠對說道：：臣下僚屬笑叔向的對君主統治者啊。凡為人臣下僚屬的人或事物，猶炮宰和五味而且進的君主統治者，君主統治者弗食，孰敢強的啊。臣下僚屬請譬的：君主統治者的人或事物、壤地啊，臣下僚屬的人或事物、草木啊，必壤地美然後草木碩大，亦君主統治者的力啊，臣下僚屬何力的有？這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 7 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「晉平公問叔向曰：「昔者齊桓公九合諸侯，一匡天下，不識臣之力也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「晉平公問叔向曰：「昔者齊桓公九合諸侯，一匡天下，不識……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-8\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":8,\"canonicalText\":\"或曰：叔向、師曠之對皆偏辭也。夫一匡天下，九合諸侯，美之大者也，非專君之力也，又非專臣之力也。昔者宮之奇在虞，僖負眾在曹，二臣之智，言中事，發中功，虞、曹俱亡者何也？此有其臣而無其君者也。且蹇叔處幹而幹亡，處秦而秦霸，非蹇叔愚於幹而智於秦也，此有君與無臣也。向曰「臣之力也」不然矣。昔者桓公宮中二市，婦閭二百，被髮而御婦人，得管仲為五伯長，失管仲得豎刁，而身死，蟲流出屍不葬。以為非臣之力也，且不以管仲為霸；以為君之力也，且不以豎刁為亂。昔者晉文公慕於齊女而亡歸，咎犯極諫，故使反晉國。故桓公以管仲合，文公以舅犯霸，而師曠曰「君之力也」又不然矣。凡五霸所以能成功名於天下者，必君臣俱有力焉。故曰：叔向、師曠之對皆偏辭也。\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-8_s-1\",\"han-fei-zi_ch-19_p-8_s-2\",\"han-fei-zi_ch-19_p-8_s-3\",\"han-fei-zi_ch-19_p-8_s-4\",\"han-fei-zi_ch-19_p-8_s-5\",\"han-fei-zi_ch-19_p-8_s-6\",\"han-fei-zi_ch-19_p-8_s-7\",\"han-fei-zi_ch-19_p-8_s-8\",\"han-fei-zi_ch-19_p-8_s-9\",\"han-fei-zi_ch-19_p-8_s-10\",\"han-fei-zi_ch-19_p-8_s-11\",\"han-fei-zi_ch-19_p-8_s-12\",\"han-fei-zi_ch-19_p-8_s-13\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 8 節）中闡述道：或說道：：叔向、師曠的對皆偏辭啊。夫一匡天下，九合諸侯，美的大的人或事物啊，絕不是專君主統治者的力啊，又絕不是專臣下僚屬的力啊。昔的人或事物宮的奇在虞，僖負眾在曹，二臣下僚屬的智，言中事，發中功，虞、曹俱亡的人或事物何啊？此有他的臣下僚屬而且無他的君主統治者的人或事物啊。且蹇叔處幹而且幹亡，處秦而且秦霸，絕不是蹇叔愚於幹而且智於秦啊，此有君主統治者與無臣下僚屬啊。向說道：臣下僚屬的力啊不然矣。昔的人或事物桓公宮中二市，婦閭二百，被髮而且御婦人，得管仲為五伯長，失管仲得豎刁，而且身死，蟲流出屍不葬。以為絕不是臣下僚屬的力啊，且不以管仲為霸；以為君主統治者的力啊，且不以豎刁為亂。昔的人或事物晉文公慕於齊女而且亡歸，咎犯極諫，所以使反晉國。所以桓公以管仲合，文公以舅犯霸，而且師曠說道：君主統治者的力啊又不然矣。凡五霸所以能成功名於天下的人或事物，必君主統治者臣下僚屬俱有力焉。因此韓絕不是子評論說道：：叔向、師曠的對皆偏辭啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 8 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「或曰：叔向、師曠之對皆偏辭也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「或曰：叔向、師曠之對皆偏辭也。夫一匡天下，九合諸侯，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-9\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":9,\"canonicalText\":\"齊桓公之時，晉客至，有司請禮，桓公曰「告仲父」者三。而優笑曰：「易哉為君，一曰仲父，二曰仲父。」桓公曰：「吾聞君人者勞於索人，佚於使人。吾得仲父已難矣，得仲父之後，何為不易乎哉！」\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-9_s-1\",\"han-fei-zi_ch-19_p-9_s-2\",\"han-fei-zi_ch-19_p-9_s-3\",\"han-fei-zi_ch-19_p-9_s-4\",\"han-fei-zi_ch-19_p-9_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 9 節）中闡述道：齊桓公的時，晉客至，有司請禮，桓公說道：告仲父的人或事物三。而且優笑說道：：易哉為君主統治者，一說道：仲父，二說道：仲父。桓公說道：：吾聞君主統治者人的人或事物勞於索人，佚於使人。吾得仲父已難矣，得仲父的後，何為不易乎哉！這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 9 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊桓公之時，晉客至，有司請禮，桓公曰「告仲父」者三」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊桓公之時，晉客至，有司請禮，桓公曰「告仲父」者三。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-10\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":10,\"canonicalText\":\"或曰：桓公之所應優，非君人者之言也。桓公以君人為勞於索人，何索人為勞哉？伊尹自以為宰幹湯，百里奚自以為虜幹穆公，虜所辱也，宰所羞也，蒙羞辱而接君上，賢者之憂世急也；然則君人者無道賢而已矣，索賢不為人主難。且官職所以任賢也，爵祿所以賞功也，設官職，陳爵祿，而士自至，君人者奚其勞哉！使人又非所佚也，人主雖使人必以度量準之，以刑名參之，以事；遇於法則行，不遇於法則止；功當其言則賞，不當則誅；以刑名收臣，以度量準下；此不可釋也，君人者焉佚哉？索人不勞，使人不佚，而桓公曰「勞於索人，佚於使人」者，不然。且桓公得管仲又不難，管仲不死其君而歸桓公，鮑叔輕官讓能而任之，桓公得管仲又不難明矣。已得管仲之後，奚遽易哉！管仲非周公旦，周公旦假為天子七年，成王壯，授之以政，非為天下計也，為其職也。夫不奪子而行天下者，必不背死君而事其讎，背死君而事其讎者，必不難奪子而行天下，不難奪子而行天下者，必不難奪其君國矣。管仲，公子糾之臣也，謀殺桓公而不能，其君死而臣桓公，管仲之取捨非周公旦未可知也。若使管仲大賢也，且為湯、武，湯、武，桀、紂之臣也，桀、紂作亂，湯、武奪之，今桓公以易居其上，是以桀、紂之行居湯、武之上，桓公危矣。若使管仲不肖人也，且為田常，田常，簡公之臣也，而弒其君，今桓公以易居其上，是以簡公之易居田常之上也，桓公又危矣。管仲非周公旦以明矣，然為湯、武與田常未可知也，為湯、武有桀、紂之危，為田常有簡公之亂也。已得仲父之後，桓公奚遽易哉！若使桓公之任管仲必知不欺己也，是知不欺主之臣也；然雖知不欺主之臣，今桓公以任管仲之專借豎刁、易牙，蟲流出屍而不葬，桓公不知臣欺主與不欺主已明矣，而任臣如彼其專也，故曰：桓公闇主。\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-10_s-1\",\"han-fei-zi_ch-19_p-10_s-2\",\"han-fei-zi_ch-19_p-10_s-3\",\"han-fei-zi_ch-19_p-10_s-4\",\"han-fei-zi_ch-19_p-10_s-5\",\"han-fei-zi_ch-19_p-10_s-6\",\"han-fei-zi_ch-19_p-10_s-7\",\"han-fei-zi_ch-19_p-10_s-8\",\"han-fei-zi_ch-19_p-10_s-9\",\"han-fei-zi_ch-19_p-10_s-10\",\"han-fei-zi_ch-19_p-10_s-11\",\"han-fei-zi_ch-19_p-10_s-12\",\"han-fei-zi_ch-19_p-10_s-13\",\"han-fei-zi_ch-19_p-10_s-14\",\"han-fei-zi_ch-19_p-10_s-15\",\"han-fei-zi_ch-19_p-10_s-16\",\"han-fei-zi_ch-19_p-10_s-17\",\"han-fei-zi_ch-19_p-10_s-18\",\"han-fei-zi_ch-19_p-10_s-19\",\"han-fei-zi_ch-19_p-10_s-20\",\"han-fei-zi_ch-19_p-10_s-21\",\"han-fei-zi_ch-19_p-10_s-22\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 10 節）中闡述道：或說道：：桓公的所應優，絕不是君主統治者人的人或事物的言啊。桓公以君主統治者人為勞於索人，何索人為勞哉？伊尹自以為宰幹湯，百里奚自以為虜幹穆公，虜所辱啊，宰所羞啊，蒙羞辱而且接君主統治者上，賢的人或事物的憂世急啊；然則君主統治者人的人或事物無道賢而且已矣，索賢不為人主難。且官職所以任賢啊，爵祿所以賞賜恩惠功啊，設官職，陳爵祿，而且士自至，君主統治者人的人或事物奚他的勞哉！使人又絕不是所佚啊，人主雖使人必以度量準的，以刑名參的，以事；遇於國家法度法規則行，不遇於國家法度法規則止；功當他的言則賞賜恩惠，不當則誅；以刑名收臣下僚屬，以度量準下；此不可釋啊，君主統治者人的人或事物焉佚哉？索人不勞，使人不佚，而且桓公說道：勞於索人，佚於使人的人或事物，不然。且桓公得管仲又不難，管仲不死他的君主統治者而且歸桓公，鮑叔輕官讓能而且任的，桓公得管仲又不難明矣。已得管仲的後，奚遽易哉！管仲絕不是周公旦，周公旦假為天子七年，成王壯，授的以政，絕不是為天下計啊，為他的職啊。夫不奪子而且行天下的人或事物，必不背死君主統治者而且事他的讎，背死君主統治者而且事他的讎的人或事物，必不難奪子而且行天下，不難奪子而且行天下的人或事物，必不難奪他的君主統治者國矣。管仲，公子糾的臣下僚屬啊，謀殺桓公而且不能，他的君主統治者死而且臣下僚屬桓公，管仲的取捨絕不是周公旦未可知啊。若使管仲大賢啊，且為湯、武，湯、武，桀、紂的臣下僚屬啊，桀、紂作亂，湯、武奪的，今桓公以易居他的上，是以桀、紂的行居湯、武的上，桓公危矣。若使管仲不肖人啊，且為田常，田常，簡公的臣下僚屬啊，而且弒他的君主統治者，今桓公以易居他的上，是以簡公的易居田常的上啊，桓公又危矣。管仲絕不是周公旦以明矣，然為湯、武與田常未可知啊，為湯、武有桀、紂的危，為田常有簡公的亂啊。已得仲父的後，桓公奚遽易哉！若使桓公的任管仲必知不欺己啊，是知不欺主的臣下僚屬啊；然雖知不欺主的臣下僚屬，今桓公以任管仲的專借豎刁、易牙，蟲流出屍而且不葬，桓公不知臣下僚屬欺主與不欺主已明矣，而且任臣下僚屬如彼他的專啊，因此韓絕不是子評論說道：：桓公闇主。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 10 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「或曰：桓公之所應優，非君人者之言也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「或曰：桓公之所應優，非君人者之言也。桓公以君人為勞於……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-11\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":11,\"canonicalText\":\"李兌治中山，苦陘令上計而入多。李兌曰：「語言辨，聽之說，不度於義，謂之窕言。無山林澤谷之利而入多者，謂之窕貨。君子不聽窕言，不受窕貨，子姑免矣。」\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-11_s-1\",\"han-fei-zi_ch-19_p-11_s-2\",\"han-fei-zi_ch-19_p-11_s-3\",\"han-fei-zi_ch-19_p-11_s-4\",\"han-fei-zi_ch-19_p-11_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 11 節）中闡述道：李兌治中山，苦陘令上計而且入多。李兌說道：：語言辨，聽的說，不度於義，謂的窕言。無山林澤谷的利而且入多的人或事物，謂的窕貨。君主統治者子不聽窕言，不受窕貨，子姑免矣。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 11 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「李兌治中山，苦陘令上計而入多」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「李兌治中山，苦陘令上計而入多。李兌曰：「語言辨，聽之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-12\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":12,\"canonicalText\":\"或曰：李子設辭曰：「夫言語辨，聽之說，不度於義者，謂之窕言。」辯、在言者，說、在聽者，言非聽者也。所謂不度於義，非謂聽者必謂所聽也。聽者非小人則君子也，小人無義必不能度之義也，君子度之義必不肯說也。夫曰「言語辨，聽之說，不度於義」者，必不誠之言也。入多之為窕貨也，未可遠行也。李子之姦弗蚤禁，使至於計，是遂過也。無術以知而入多，入多者，穰也，雖倍入將奈何！舉事慎陰陽之和，種樹節四時之適，無早晚之失，寒溫之災，則入多。不以小功妨大務，不以私欲害人事，丈夫盡於耕農，婦人力於織紝，則入多。務於畜養之理，察於土地之宜，六畜遂，五穀殖，則入多。明於權計，審於地形、舟車機械之利，用力少致功大，則入多。利商市關梁之行，能以所有致所無，客商歸之，外貨留之，儉於財用，節於衣食，宮室器械，周於資用，不事玩好，則入多。入多、皆人為也。若天事、風雨時，寒溫適，土地不加大，而有豐年之功，則入多。人事、天功，二物者皆入多，非山林澤谷之利也。夫無山林澤谷之利入多，因謂之窕貨者，無術之言也。\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-12_s-1\",\"han-fei-zi_ch-19_p-12_s-2\",\"han-fei-zi_ch-19_p-12_s-3\",\"han-fei-zi_ch-19_p-12_s-4\",\"han-fei-zi_ch-19_p-12_s-5\",\"han-fei-zi_ch-19_p-12_s-6\",\"han-fei-zi_ch-19_p-12_s-7\",\"han-fei-zi_ch-19_p-12_s-8\",\"han-fei-zi_ch-19_p-12_s-9\",\"han-fei-zi_ch-19_p-12_s-10\",\"han-fei-zi_ch-19_p-12_s-11\",\"han-fei-zi_ch-19_p-12_s-12\",\"han-fei-zi_ch-19_p-12_s-13\",\"han-fei-zi_ch-19_p-12_s-14\",\"han-fei-zi_ch-19_p-12_s-15\",\"han-fei-zi_ch-19_p-12_s-16\",\"han-fei-zi_ch-19_p-12_s-17\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 12 節）中闡述道：或說道：：李子設辭說道：：夫言語辨，聽的說，不度於義的人或事物，謂的窕言。辯、在言的人或事物，說、在聽的人或事物，言絕不是聽的人或事物啊。所謂不度於義，絕不是謂聽的人或事物必謂所聽啊。聽的人或事物絕不是小人則君主統治者子啊，小人無義必不能度的義啊，君主統治者子度的義必不肯說啊。夫說道：言語辨，聽的說，不度於義的人或事物，必不誠的言啊。入多的為窕貨啊，未可遠行啊。李子的姦弗蚤禁，使至於計，是遂過啊。無御臣心術權謀以知而且入多，入多的人或事物，穰啊，雖倍入將奈何！舉事慎陰陽的和，種樹節四時的適，無早晚的失，寒溫的災，則入多。不以小功妨大務，不以私欲害人事，丈夫盡於耕農，婦人力於織紝，則入多。務於畜養的理，察於土地的宜，六畜遂，五穀殖，則入多。明於權計，審於地形、舟車機械的利，用力少致功大，則入多。利商市關梁的行，能以所有致所無，客商歸的，外貨留的，儉於財用，節於衣食，宮室器械，周於資用，不事玩好，則入多。入多、皆人為啊。若天事、風雨時，寒溫適，土地不加大，而且有豐年的功，則入多。人事、天功，二物的人或事物皆入多，絕不是山林澤谷的利啊。夫無山林澤谷的利入多，因謂的窕貨的人或事物，無御臣心術權謀的言啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 12 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「或曰：李子設辭曰：「夫言語辨，聽之說，不度於義者，謂之窕言」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「或曰：李子設辭曰：「夫言語辨，聽之說，不度於義者，謂……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-13\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":13,\"canonicalText\":\"趙簡子圍衛之郛郭，犀楯、犀櫓立於矢石之所不及，鼓之而士不起，簡子投枹曰：「烏乎！吾之士數弊也。」行人燭過免冑而對曰：「臣聞之，亦有君之不能耳，士無弊者。昔者吾先君獻公並國十七，服國三十八，戰十有二勝，是民之用也。獻公沒，惠公即位，淫衍暴亂，身好玉女，秦人恣侵，去絳十七里，亦是人之用也。惠公沒，文公授之，圍衛、取鄴，城濮之戰，五敗荊人，取尊名於天下，亦此人之用也。亦有君不能耳，士無弊也。」簡子乃去楯、櫓立矢石之所及，鼓之而士乘之，戰大勝。簡子曰：「與吾得革車千乘，不如聞行人燭過之一言也。」\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-13_s-1\",\"han-fei-zi_ch-19_p-13_s-2\",\"han-fei-zi_ch-19_p-13_s-3\",\"han-fei-zi_ch-19_p-13_s-4\",\"han-fei-zi_ch-19_p-13_s-5\",\"han-fei-zi_ch-19_p-13_s-6\",\"han-fei-zi_ch-19_p-13_s-7\",\"han-fei-zi_ch-19_p-13_s-8\",\"han-fei-zi_ch-19_p-13_s-9\",\"han-fei-zi_ch-19_p-13_s-10\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 13 節）中闡述道：趙簡子圍衛的郛郭，犀楯、犀櫓立於矢石的所不及，鼓的而且士不起，簡子投枹說道：：烏乎！吾的士數弊啊。行人燭過免冑而且對說道：：臣下僚屬聞的，亦有君主統治者的不能耳，士無弊的人或事物。昔的人或事物吾先君主統治者獻公並國十七，服國三十八，戰十有二勝，是民的用啊。獻公沒，惠公即位，淫衍暴亂，身好玉女，秦人恣侵，去絳十七里，亦是人的用啊。惠公沒，文公授的，圍衛、取鄴，城濮的戰，五敗荊人，取尊名於天下，亦此人的用啊。亦有君主統治者不能耳，士無弊啊。簡子乃去楯、櫓立矢石的所及，鼓的而且士乘的，戰大勝。簡子說道：：與吾得革車千乘，不如聞行人燭過的一言啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 13 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「趙簡子圍衛之郛郭，犀楯、犀櫓立於矢石之所不及，鼓之而士不起，簡子投枹曰：「烏乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「趙簡子圍衛之郛郭，犀楯、犀櫓立於矢石之所不及，鼓之而……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-19_p-14\",\"chapterId\":\"han-fei-zi_ch-19\",\"order\":14,\"canonicalText\":\"或曰：行人未有以說也，乃道惠公以此人是敗，文公以此人是霸，未見所以用人也；簡子未可以速去楯、櫓也。嚴親在圍，輕犯矢石，孝子之所愛親也。孝子愛親，百數之一也。今以為身處危而人尚可戰，是以百族之子於上皆若孝子之愛親也，是行人之誣也。好利惡害，夫人之所有也。賞厚而信，人輕敵矣；刑重而必，失人不北矣。長行徇上，數百不一失。喜利畏罪，人莫不然。將眾者不出乎莫不然之數，而道乎百無一人之行，行人未知用眾之道也。\",\"sentenceIds\":[\"han-fei-zi_ch-19_p-14_s-1\",\"han-fei-zi_ch-19_p-14_s-2\",\"han-fei-zi_ch-19_p-14_s-3\",\"han-fei-zi_ch-19_p-14_s-4\",\"han-fei-zi_ch-19_p-14_s-5\",\"han-fei-zi_ch-19_p-14_s-6\",\"han-fei-zi_ch-19_p-14_s-7\",\"han-fei-zi_ch-19_p-14_s-8\",\"han-fei-zi_ch-19_p-14_s-9\",\"han-fei-zi_ch-19_p-14_s-10\",\"han-fei-zi_ch-19_p-14_s-11\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・難二》（第 14 節）中闡述道：或說道：：行人未有以說啊，乃道惠公以此人是敗，文公以此人是霸，未見所以用人啊；簡子未可以速去楯、櫓啊。嚴親在圍，輕犯矢石，孝子的所愛親啊。孝子愛親，百數的一啊。今以為身處危而且人尚可戰，是以百族的子於上皆若孝子的愛親啊，是行人的誣啊。好利惡害，夫人的所有啊。賞賜恩惠厚而且信，人輕敵矣；刑重而且必，失人不北矣。長行徇上，數百不一失。喜利畏罪，人莫不然。將眾的人或事物不出乎莫不然的數，而且道乎百無一人的行，行人未知用眾的道啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈難二〉（第 14 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「或曰：行人未有以說也，乃道惠公以此人是敗，文公以此人是霸，未見所以用人也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「或曰：行人未有以說也，乃道惠公以此人是敗，文公以此人……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"han-fei-zi_ch-19_p-1_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-1\",\"order\":1,\"canonicalText\":\"景公過晏子曰：「子宮小，近市，請徙子家豫章之圃。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-1_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-1\",\"order\":2,\"canonicalText\":\"」晏子再拜而辭曰：「且嬰家貧，待市食，而朝暮趨之，不可以遠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-1_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-1\",\"order\":3,\"canonicalText\":\"」景公笑曰：「子家習市，識貴賤乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-1_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-1\",\"order\":4,\"canonicalText\":\"」是時景公繁於刑，晏子對曰：「踴貴而屨賤。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-1_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-1\",\"order\":5,\"canonicalText\":\"」景公曰：「何故？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-1_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-1\",\"order\":6,\"canonicalText\":\"」對曰：「刑多也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-1_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-1\",\"order\":7,\"canonicalText\":\"」景公造然變色曰：「寡人其暴乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-1_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-1\",\"order\":8,\"canonicalText\":\"」於是損刑五。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-2_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-2\",\"order\":1,\"canonicalText\":\"或曰：晏子之貴踴，非其誠也，欲便辭以止多刑也，此不察治之患也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-2_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-2\",\"order\":2,\"canonicalText\":\"夫刑當無多，不當無少，無以不當聞，而以太多說，無術之患也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-2_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-2\",\"order\":3,\"canonicalText\":\"敗軍之誅以千百數，猶北不止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-2_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-2\",\"order\":4,\"canonicalText\":\"即治亂之刑如恐不勝，而姦尚不盡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-2_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-2\",\"order\":5,\"canonicalText\":\"今晏子不察其當否，而以太多為說，不亦妄乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-2_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-2\",\"order\":6,\"canonicalText\":\"夫惜草茅者耗禾穗，惠盜賊者傷良民。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-2_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-2\",\"order\":7,\"canonicalText\":\"今緩刑罰，行寬惠，是利姦邪而害善人也，此非所以為治也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-3_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-3\",\"order\":1,\"canonicalText\":\"齊桓公飲酒醉，遺其冠，恥之，三日不朝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-3_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-3\",\"order\":2,\"canonicalText\":\"管仲曰：「此非有國之恥也，公胡其不雪之以政？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-3_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-3\",\"order\":3,\"canonicalText\":\"」公曰：「胡其善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-3_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-3\",\"order\":4,\"canonicalText\":\"」因發倉囷，賜貧窮；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-3_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-3\",\"order\":5,\"canonicalText\":\"論囹圄，出薄惱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-3_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-3\",\"order\":6,\"canonicalText\":\"處三日而民歌之曰：「公胡不復遺冠乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-3_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-3\",\"order\":7,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-4_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-4\",\"order\":1,\"canonicalText\":\"或曰：管仲雪桓公之恥於小人，而生桓公之恥於君子矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-4_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-4\",\"order\":2,\"canonicalText\":\"使桓公發倉囷而賜貧窮，論囹圄而出薄惱，非義也，不可以雪恥使之而義也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-4_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-4\",\"order\":3,\"canonicalText\":\"桓公宿義，須遺冠而後行之，則是桓公行義，非為遺冠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-4_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-4\",\"order\":4,\"canonicalText\":\"是雖雪遺冠之恥於小人，而亦遺義之恥於君子矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-4_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-4\",\"order\":5,\"canonicalText\":\"且夫發囷倉而賜貧窮者，是賞無功也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-4_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-4\",\"order\":6,\"canonicalText\":\"論囹圄而出薄惱者，是不誅過也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-4_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-4\",\"order\":7,\"canonicalText\":\"夫賞無功則民偷幸而望於上，不誅過則民不懲而易為非，此亂之本也，安可以雪恥哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-5_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-5\",\"order\":1,\"canonicalText\":\"昔者文王侵孟、克莒、舉酆，三舉事而紂惡之，文王乃懼，請入洛西之地、赤壤之國、方千里以請解炮烙之刑，天下皆說。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-5_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-5\",\"order\":2,\"canonicalText\":\"仲尼聞之曰：「仁哉文王！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-5_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-5\",\"order\":3,\"canonicalText\":\"輕千里之國而請解炮烙之刑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-5_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-5\",\"order\":4,\"canonicalText\":\"智哉文王！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-5_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-5\",\"order\":5,\"canonicalText\":\"出千里之地而得天下之心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-5_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-5\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-6_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-6\",\"order\":1,\"canonicalText\":\"或曰：仲尼以文王為智也，不亦過乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-6_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-6\",\"order\":2,\"canonicalText\":\"夫智者知禍難之地而闢之者也，是以身不及於患也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-6_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-6\",\"order\":3,\"canonicalText\":\"使文王所以見惡於紂者，以其不得人心耶？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-6_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-6\",\"order\":4,\"canonicalText\":\"則雖索人心以解惡可也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-6_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-6\",\"order\":5,\"canonicalText\":\"紂以其大得人心而惡之，己又輕地以收人心，是重見疑也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-6_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-6\",\"order\":6,\"canonicalText\":\"固其所以桎梏囚於羑里也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-6_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-6\",\"order\":7,\"canonicalText\":\"鄭長者有言：「體道，無為、無見也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-6_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-6\",\"order\":8,\"canonicalText\":\"」此最宜於文王矣，不使人疑之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-6_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-6\",\"order\":9,\"canonicalText\":\"仲尼以文王為智，未及此論也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-7_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-7\",\"order\":1,\"canonicalText\":\"晉平公問叔向曰：「昔者齊桓公九合諸侯，一匡天下，不識臣之力也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-7_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-7\",\"order\":2,\"canonicalText\":\"君之力也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-7_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-7\",\"order\":3,\"canonicalText\":\"」叔向對曰：「管仲善制割，賓胥無善削縫，隰朋善純緣，衣成，君舉而服之，亦臣之力也，君何力之有？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-7_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-7\",\"order\":4,\"canonicalText\":\"」師曠伏琴而笑之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-7_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-7\",\"order\":5,\"canonicalText\":\"公曰：「太師奚笑也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-7_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-7\",\"order\":6,\"canonicalText\":\"」師曠對曰：「臣笑叔向之對君也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-7_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-7\",\"order\":7,\"canonicalText\":\"凡為人臣者，猶炮宰和五味而進之君，君弗食，孰敢強之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-7_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-7\",\"order\":8,\"canonicalText\":\"臣請譬之：君者、壤地也，臣者、草木也，必壤地美然後草木碩大，亦君之力也，臣何力之有？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-7_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-7\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":1,\"canonicalText\":\"或曰：叔向、師曠之對皆偏辭也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":2,\"canonicalText\":\"夫一匡天下，九合諸侯，美之大者也，非專君之力也，又非專臣之力也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":3,\"canonicalText\":\"昔者宮之奇在虞，僖負眾在曹，二臣之智，言中事，發中功，虞、曹俱亡者何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":4,\"canonicalText\":\"此有其臣而無其君者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":5,\"canonicalText\":\"且蹇叔處幹而幹亡，處秦而秦霸，非蹇叔愚於幹而智於秦也，此有君與無臣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":6,\"canonicalText\":\"向曰「臣之力也」不然矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":7,\"canonicalText\":\"昔者桓公宮中二市，婦閭二百，被髮而御婦人，得管仲為五伯長，失管仲得豎刁，而身死，蟲流出屍不葬。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":8,\"canonicalText\":\"以為非臣之力也，且不以管仲為霸；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":9,\"canonicalText\":\"以為君之力也，且不以豎刁為亂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":10,\"canonicalText\":\"昔者晉文公慕於齊女而亡歸，咎犯極諫，故使反晉國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":11,\"canonicalText\":\"故桓公以管仲合，文公以舅犯霸，而師曠曰「君之力也」又不然矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":12,\"canonicalText\":\"凡五霸所以能成功名於天下者，必君臣俱有力焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-8_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-8\",\"order\":13,\"canonicalText\":\"故曰：叔向、師曠之對皆偏辭也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-9_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-9\",\"order\":1,\"canonicalText\":\"齊桓公之時，晉客至，有司請禮，桓公曰「告仲父」者三。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-9_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-9\",\"order\":2,\"canonicalText\":\"而優笑曰：「易哉為君，一曰仲父，二曰仲父。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-9_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-9\",\"order\":3,\"canonicalText\":\"」桓公曰：「吾聞君人者勞於索人，佚於使人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-9_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-9\",\"order\":4,\"canonicalText\":\"吾得仲父已難矣，得仲父之後，何為不易乎哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-9_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-9\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":1,\"canonicalText\":\"或曰：桓公之所應優，非君人者之言也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":2,\"canonicalText\":\"桓公以君人為勞於索人，何索人為勞哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":3,\"canonicalText\":\"伊尹自以為宰幹湯，百里奚自以為虜幹穆公，虜所辱也，宰所羞也，蒙羞辱而接君上，賢者之憂世急也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":4,\"canonicalText\":\"然則君人者無道賢而已矣，索賢不為人主難。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":5,\"canonicalText\":\"且官職所以任賢也，爵祿所以賞功也，設官職，陳爵祿，而士自至，君人者奚其勞哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":6,\"canonicalText\":\"使人又非所佚也，人主雖使人必以度量準之，以刑名參之，以事；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":7,\"canonicalText\":\"遇於法則行，不遇於法則止；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":8,\"canonicalText\":\"功當其言則賞，不當則誅；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":9,\"canonicalText\":\"以刑名收臣，以度量準下；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":10,\"canonicalText\":\"此不可釋也，君人者焉佚哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":11,\"canonicalText\":\"索人不勞，使人不佚，而桓公曰「勞於索人，佚於使人」者，不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":12,\"canonicalText\":\"且桓公得管仲又不難，管仲不死其君而歸桓公，鮑叔輕官讓能而任之，桓公得管仲又不難明矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":13,\"canonicalText\":\"已得管仲之後，奚遽易哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":14,\"canonicalText\":\"管仲非周公旦，周公旦假為天子七年，成王壯，授之以政，非為天下計也，為其職也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":15,\"canonicalText\":\"夫不奪子而行天下者，必不背死君而事其讎，背死君而事其讎者，必不難奪子而行天下，不難奪子而行天下者，必不難奪其君國矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":16,\"canonicalText\":\"管仲，公子糾之臣也，謀殺桓公而不能，其君死而臣桓公，管仲之取捨非周公旦未可知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":17,\"canonicalText\":\"若使管仲大賢也，且為湯、武，湯、武，桀、紂之臣也，桀、紂作亂，湯、武奪之，今桓公以易居其上，是以桀、紂之行居湯、武之上，桓公危矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":18,\"canonicalText\":\"若使管仲不肖人也，且為田常，田常，簡公之臣也，而弒其君，今桓公以易居其上，是以簡公之易居田常之上也，桓公又危矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":19,\"canonicalText\":\"管仲非周公旦以明矣，然為湯、武與田常未可知也，為湯、武有桀、紂之危，為田常有簡公之亂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-20\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":20,\"canonicalText\":\"已得仲父之後，桓公奚遽易哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-21\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":21,\"canonicalText\":\"若使桓公之任管仲必知不欺己也，是知不欺主之臣也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-10_s-22\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-10\",\"order\":22,\"canonicalText\":\"然雖知不欺主之臣，今桓公以任管仲之專借豎刁、易牙，蟲流出屍而不葬，桓公不知臣欺主與不欺主已明矣，而任臣如彼其專也，故曰：桓公闇主。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-11_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-11\",\"order\":1,\"canonicalText\":\"李兌治中山，苦陘令上計而入多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-11_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-11\",\"order\":2,\"canonicalText\":\"李兌曰：「語言辨，聽之說，不度於義，謂之窕言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-11_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-11\",\"order\":3,\"canonicalText\":\"無山林澤谷之利而入多者，謂之窕貨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-11_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-11\",\"order\":4,\"canonicalText\":\"君子不聽窕言，不受窕貨，子姑免矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-11_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-11\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":1,\"canonicalText\":\"或曰：李子設辭曰：「夫言語辨，聽之說，不度於義者，謂之窕言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":2,\"canonicalText\":\"」辯、在言者，說、在聽者，言非聽者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":3,\"canonicalText\":\"所謂不度於義，非謂聽者必謂所聽也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":4,\"canonicalText\":\"聽者非小人則君子也，小人無義必不能度之義也，君子度之義必不肯說也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":5,\"canonicalText\":\"夫曰「言語辨，聽之說，不度於義」者，必不誠之言也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":6,\"canonicalText\":\"入多之為窕貨也，未可遠行也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":7,\"canonicalText\":\"李子之姦弗蚤禁，使至於計，是遂過也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":8,\"canonicalText\":\"無術以知而入多，入多者，穰也，雖倍入將奈何！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":9,\"canonicalText\":\"舉事慎陰陽之和，種樹節四時之適，無早晚之失，寒溫之災，則入多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":10,\"canonicalText\":\"不以小功妨大務，不以私欲害人事，丈夫盡於耕農，婦人力於織紝，則入多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":11,\"canonicalText\":\"務於畜養之理，察於土地之宜，六畜遂，五穀殖，則入多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":12,\"canonicalText\":\"明於權計，審於地形、舟車機械之利，用力少致功大，則入多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":13,\"canonicalText\":\"利商市關梁之行，能以所有致所無，客商歸之，外貨留之，儉於財用，節於衣食，宮室器械，周於資用，不事玩好，則入多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":14,\"canonicalText\":\"入多、皆人為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":15,\"canonicalText\":\"若天事、風雨時，寒溫適，土地不加大，而有豐年之功，則入多。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":16,\"canonicalText\":\"人事、天功，二物者皆入多，非山林澤谷之利也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-12_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-12\",\"order\":17,\"canonicalText\":\"夫無山林澤谷之利入多，因謂之窕貨者，無術之言也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":1,\"canonicalText\":\"趙簡子圍衛之郛郭，犀楯、犀櫓立於矢石之所不及，鼓之而士不起，簡子投枹曰：「烏乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":2,\"canonicalText\":\"吾之士數弊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":3,\"canonicalText\":\"」行人燭過免冑而對曰：「臣聞之，亦有君之不能耳，士無弊者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":4,\"canonicalText\":\"昔者吾先君獻公並國十七，服國三十八，戰十有二勝，是民之用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":5,\"canonicalText\":\"獻公沒，惠公即位，淫衍暴亂，身好玉女，秦人恣侵，去絳十七里，亦是人之用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":6,\"canonicalText\":\"惠公沒，文公授之，圍衛、取鄴，城濮之戰，五敗荊人，取尊名於天下，亦此人之用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":7,\"canonicalText\":\"亦有君不能耳，士無弊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":8,\"canonicalText\":\"」簡子乃去楯、櫓立矢石之所及，鼓之而士乘之，戰大勝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":9,\"canonicalText\":\"簡子曰：「與吾得革車千乘，不如聞行人燭過之一言也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-13_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-13\",\"order\":10,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":1,\"canonicalText\":\"或曰：行人未有以說也，乃道惠公以此人是敗，文公以此人是霸，未見所以用人也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":2,\"canonicalText\":\"簡子未可以速去楯、櫓也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":3,\"canonicalText\":\"嚴親在圍，輕犯矢石，孝子之所愛親也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":4,\"canonicalText\":\"孝子愛親，百數之一也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":5,\"canonicalText\":\"今以為身處危而人尚可戰，是以百族之子於上皆若孝子之愛親也，是行人之誣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":6,\"canonicalText\":\"好利惡害，夫人之所有也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":7,\"canonicalText\":\"賞厚而信，人輕敵矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":8,\"canonicalText\":\"刑重而必，失人不北矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":9,\"canonicalText\":\"長行徇上，數百不一失。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":10,\"canonicalText\":\"喜利畏罪，人莫不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-19_p-14_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-19\",\"passageId\":\"han-fei-zi_ch-19_p-14\",\"order\":11,\"canonicalText\":\"將眾者不出乎莫不然之數，而道乎百無一人之行，行人未知用眾之道也。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
